import json
import sys

def pathfind():
    global input_data
    # Robustly retrieve input_data from global scope or sys.argv
    if 'input_data' not in globals():
        try:
            input_data = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {}
        except Exception:
            input_data = {}

    start_x = int(input_data.get('start_x', -1))
    start_y = int(input_data.get('start_y', -1))
    target_x = int(input_data.get('target_x', -1))
    target_y = int(input_data.get('target_y', -1))
    map_id = input_data.get('map_id', '0_201')

    # Static collision database for Rocket Hideout
    blocked_tiles = set()

    if map_id == '0_199': # B1F
        # Western partition wall
        for y in range(35):
            blocked_tiles.add((8, y))
        # Row 16 horizontal wall
        for x in range(9, 24):
            blocked_tiles.add((x, 16))
        # Counters on Row 16
        blocked_tiles.add((28, 16))
        # Impassable step tiles from North to South
        blocked_tiles.add((24, 16))
        blocked_tiles.add((25, 16))

    elif map_id == '0_200': # B2F
        # Row 16 horizontal divider wall (East portion)
        for x in range(18, 28):
            blocked_tiles.add((x, 16))
        # Column 18 vertical partition wall on rows 6 to 9
        for y in range(6, 10):
            blocked_tiles.add((18, y))
        # Column 17 green blocks on rows 8, 9, 12
        for y in [8, 9, 12]:
            blocked_tiles.add((17, y))
        # Column 24 plants/statues on rows 8 to 13
        for y in range(8, 14):
            blocked_tiles.add((24, y))
        # Column 23 partition wall on rows 6 to 13
        for y in range(6, 14):
            blocked_tiles.add((23, y))
        # Obstacles listed in Locations/RocketHideout_B2F_SpinnerMaze
        blocked_tiles.add((6, 7))
        for x in [2, 3, 4, 6, 8, 10]:
            blocked_tiles.add((x, 8))
        for x in [2, 5, 6, 7, 8, 9, 11]:
            blocked_tiles.add((x, 10))
        blocked_tiles.add((2, 11))
        blocked_tiles.add((11, 11))
        for x in [2, 4, 5, 7, 9, 11]:
            blocked_tiles.add((x, 12))
        for x in [5, 6, 7, 9]:
            blocked_tiles.add((x, 13))
        blocked_tiles.add((2, 14))
        blocked_tiles.add((3, 14))
        for x in range(11, 16):
            blocked_tiles.add((x, 24))

        # Screen-verified obstacles on B2F (from turns 35582 and 35602)
        for x in range(15, 18):
            blocked_tiles.add((x, 12))
        blocked_tiles.add((15, 13))
        for x in range(12, 16):
            blocked_tiles.add((x, 14))
        for y in range(14, 17):
            blocked_tiles.add((17, y))
        blocked_tiles.add((15, 15))
        for x in range(12, 14):
            blocked_tiles.add((x, 15))
        for y in range(19, 23):
            blocked_tiles.add((15, y))
        blocked_tiles.add((14, 19))
        for x in range(11, 14):
            blocked_tiles.add((x, 21))
        for x in range(17, 19):
            blocked_tiles.add((x, 17))
        for y in range(18, 20):
            blocked_tiles.add((17, y))
        for y in range(14, 17):
            blocked_tiles.add((18, y))
        for y in range(18, 20):
            blocked_tiles.add((18, y))
        for x in range(19, 21):
            blocked_tiles.add((x, 16))
        blocked_tiles.add((18, 22))

    elif map_id == '0_201': # B3F
        # Column 21 partition wall
        for y in range(8, 17):
            blocked_tiles.add((21, y))
        # Column 23 partition wall
        for y in range(17, 27):
            blocked_tiles.add((23, y))
        # Row 16 solid wall
        for x in range(9, 24):
            blocked_tiles.add((x, 16))
        # Barriers: column 9 (rows 22-25) and columns 12-13 (rows 22-24)
        for y in range(22, 26):
            blocked_tiles.add((9, y))
        for x in [12, 13]:
            for y in range(22, 25):
                blocked_tiles.add((x, y))
        # Central Block (Columns 12-17, Rows 18-21)
        for x in range(12, 18):
            for y in range(18, 22):
                blocked_tiles.add((x, y))
        # Column 22 on rows 19 to 23
        for y in range(19, 24):
            blocked_tiles.add((22, y))
        # Screen-verified B3F obstacles (Turn 35701)
        # Row 8 solid tables (columns 8-18)
        for x in range(8, 19):
            blocked_tiles.add((x, 8))
        # Row 10 solid green blocks
        for x in range(9, 13):
            blocked_tiles.add((x, 10))
        for x in range(15, 20):
            blocked_tiles.add((x, 10))
        # Up-spinner at (19, 17)
        blocked_tiles.add((19, 17))

    elif map_id == '0_202': # B4F
        # Row 4 horizontal divider
        for x in range(9, 29):
            blocked_tiles.add((x, 4))
        # Row 9 solid table
        for x in range(22, 26):
            blocked_tiles.add((x, 9))
        # Row 13 solid table
        for x in range(24, 29):
            blocked_tiles.add((x, 13))
        # Column 21 solid partition wall on rows 8 to 13
        for y in range(8, 14):
            blocked_tiles.add((21, y))
        # Column 19 solid on rows 13-15
        for y in range(13, 16):
            blocked_tiles.add((19, y))

    if start_x < 0 or start_y < 0 or target_x < 0 or target_y < 0:
        print("[]")
        return

    if (start_x, start_y) == (target_x, target_y):
        print("[]")
        return

    from collections import deque
    queue = deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    directions = [
        ('Up', (0, -1)),
        ('Down', (0, 1)),
        ('Left', (-1, 0)),
        ('Right', (1, 0))
    ]

    path_found = False
    buttons = []

    while queue:
        curr_x, curr_y, curr_path = queue.popleft()

        if (curr_x, curr_y) == (target_x, target_y):
            path_found = True
            buttons = curr_path
            break

        for btn, (dx, dy) in directions:
            nx, ny = curr_x + dx, curr_y + dy
            if 0 <= nx < 40 and 0 <= ny < 35:
                if (nx, ny) not in blocked_tiles and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, curr_path + [btn]))

    if path_found:
        print(json.dumps(buttons))
    else:
        print("[]")

if __name__ == '__main__':
    pathfind()
